import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_max_reduce(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

#include <cmath>
#include <limits>

using namespace cute;

template <typename scalar_t>
__global__ void cute_max_reduce_kernel(
    const scalar_t* __restrict__ x,
    scalar_t* __restrict__ y,
    int d0,
    int d1,
    int d2,
    int dim,
    int output_size)
{
    int output_idx = blockIdx.x;
    if (output_idx >= output_size) {
        return;
    }

    Tensor input = make_tensor(
        make_gmem_ptr(x),
        make_shape(d0, d1, d2),
        make_stride(d1 * d2, d2, Int<1>{}));

    scalar_t local_max = -std::numeric_limits<scalar_t>::infinity();
    int reduce_size = 0;

    if (dim == 0) {
        int i = output_idx / d2;
        int k = output_idx - i * d2;
        reduce_size = d0;

        for (int r = threadIdx.x; r < reduce_size; r += blockDim.x) {
            scalar_t value = input(r, i, k);
            if (isnan(static_cast<double>(value)) ||
                isnan(static_cast<double>(local_max))) {
                local_max = value;
            } else if (value > local_max) {
                local_max = value;
            }
        }
    } else if (dim == 1) {
        int b = output_idx / d2;
        int k = output_idx - b * d2;
        reduce_size = d1;

        for (int r = threadIdx.x; r < reduce_size; r += blockDim.x) {
            scalar_t value = input(b, r, k);
            if (isnan(static_cast<double>(value)) ||
                isnan(static_cast<double>(local_max))) {
                local_max = value;
            } else if (value > local_max) {
                local_max = value;
            }
        }
    } else {
        int b = output_idx / d1;
        int i = output_idx - b * d1;
        reduce_size = d2;

        for (int r = threadIdx.x; r < reduce_size; r += blockDim.x) {
            scalar_t value = input(b, i, r);
            if (isnan(static_cast<double>(value)) ||
                isnan(static_cast<double>(local_max))) {
                local_max = value;
            } else if (value > local_max) {
                local_max = value;
            }
        }
    }

    extern __shared__ unsigned char shared_raw[];
    scalar_t* shared = reinterpret_cast<scalar_t*>(shared_raw);

    shared[threadIdx.x] = local_max;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            scalar_t other = shared[threadIdx.x + stride];
            scalar_t current = shared[threadIdx.x];

            if (isnan(static_cast<double>(other)) ||
                isnan(static_cast<double>(current))) {
                shared[threadIdx.x] = other;
            } else if (other > current) {
                shared[threadIdx.x] = other;
            }
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        y[output_idx] = shared[0];
    }
}

torch::Tensor cute_max_reduce(torch::Tensor x, int64_t dim)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 3, "x must be a 3D tensor");
    TORCH_CHECK(dim >= 0 && dim < 3, "dim must be 0, 1, or 2");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat ||
        x.scalar_type() == at::kDouble ||
        x.scalar_type() == at::kHalf,
        "supported dtypes are float16, float32, and float64");

    auto x_contiguous = x.contiguous();

    int d0 = static_cast<int>(x_contiguous.size(0));
    int d1 = static_cast<int>(x_contiguous.size(1));
    int d2 = static_cast<int>(x_contiguous.size(2));

    std::vector<int64_t> output_shape;
    if (dim == 0) {
        output_shape = {d1, d2};
    } else if (dim == 1) {
        output_shape = {d0, d2};
    } else {
        output_shape = {d0, d1};
    }

    auto output = torch::empty(output_shape, x.options());
    int output_size = static_cast<int>(output.numel());

    constexpr int threads = 256;
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(
        x.scalar_type(),
        "cute_max_reduce",
        [&] {
            cute_max_reduce_kernel<scalar_t>
                <<<output_size, threads, threads * sizeof(scalar_t), stream>>>(
                    x_contiguous.data_ptr<scalar_t>(),
                    output.data_ptr<scalar_t>(),
                    d0,
                    d1,
                    d2,
                    static_cast<int>(dim),
                    output_size);
        });

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE max-reduction kernel launch failed");

    return output;
}
"""

cute_ext = load_inline(
    name="cute_max_reduce_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_max_reduce"],
    extra_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_max_reduce(x, self.dim)

